# Surah Yusuf (chapter 12) — part 6: ayat 51-60 (IDs 1647-1656)
SURAH = 12

ENTRIES = {
1647: (
"بادشاہ — نے کہا — تمہیں کیا ہوا — جب — تم نے — یوسفؑ کو اپنی طرف بلایا — انہوں نے کہا — اللہ — پاک ہے — ہم نے — اس کے بارے میں — کوئی برائی — نہیں جانی — عزیز کی بیوی — نے کہا — اب — حق — ظاہر ہو گیا — میں نے — اسے — اپنی طرف بلایا — اور — یقیناً — وہ سچ بولنے والوں — میں سے — ہے",
"""۱۔ بادشاہ — کے سوال — پر — سب عورت — گواہی دیں؛ عزیز کی بیوی — اعتراف — کرتی ہے۔
۲۔ ’’قَالَ مَا خَطْبُكُنَّ إِذْ رَاوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِ قُلْنَ حَاشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوءٍ قَالَتِ امْرَأَتُ الْعَزِيزِ الْآنَ حَصْحَصَ الْحَقُّ أَنَا رَاوَدتُّهُ عَن نَّفْسِهِ وَإِنَّهُ لَمِنَ الصَّادِقِينَ‘‘ — بادشاہ — نے کہا — تمہیں کیا ہوا — جب — تم نے — یوسفؑ کو اپنی طرف بلایا — انہوں نے کہا — اللہ — پاک ہے — ہم نے — اس کے بارے میں — کوئی برائی — نہیں جانی — عزیز کی بیوی — نے کہا — اب — حق — ظاہر ہو گیا — میں نے — اسے — اپنی طرف بلایا — اور — یقیناً — وہ سچ بولنے والوں — میں سے — ہے — یعنی بادشاہ — نے عورتوں — سے پوچھا — عزیز کی بیوی نے کہا — اب حق — ظاہر ہو گیا — میں نے — اسے — اپنی طرف — بلایا — اور یقیناً — وہ — سچ بولنے والوں — میں — سے ہے۔
۳۔ عملی سبق: حق — دیر سے — ہی سہی — بالآخر — ظاہر — ہوتا — ہے۔"""
),
1648: (
"یہ — اس لیے — کہ — وہ — جانے — کہ — میں نے — اس — کو — پیچھے سے — دھوکہ — نہیں دیا — اور — بے شک اللہ — دھوکہ بازوں — کی چال — کو — راہ نہیں دکھاتا",
"""۱۔ عزیز کی بیوی — اپنی براءت — اور — اللہ کی سنّت — بیان کرتی ہے۔
۲۔ ’’ذَٰلِكَ لِيَعْلَمَ أَنِّي لَمْ أَخُنْهُ بِالْغَيْبِ وَأَنَّ اللَّهَ لَا يَهْدِي كَيْدَ الْخَائِنِينَ‘‘ — یہ — اس لیے — کہ — وہ — جانے — کہ — میں نے — اس — کو — پیچھے سے — دھوکہ — نہیں دیا — اور — بے شک اللہ — دھوکہ بازوں — کی چال — کو — راہ نہیں دکھاتا — یعنی عزیز کی بیوی — نے کہا — یہ — اس لیے کہ — بادشاہ — جانے — میں نے اسے — دھوکہ — نہیں دیا — پیچھے — سے — اور — بے شک — اللہ — دھوکہ بازوں — کی چال — کو — راہ — نہیں دکھاتا۔
۳۔ عملی سبق: خائن کی چال — بالآخر — ناکام — ہوتی ہے۔"""
),
1649: (
"اور — میں — اپنے نفس — کی صفائی نہیں دیتی — بے شک — نفس — ہمیشہ — برائی — کا حکم دیتا ہے — مگر — وہ — جس — پر — میرا رب رحم کرتا ہے — بے شک — میرا رب — بخشنے والا مہربان — ہے",
"""۱۔ نفس — برائی کی طرف مائل — مگر — اللہ کی رحمت — سے — بچنے والا۔
۲۔ ’’وَمَا أُبَرِّئُ نَفْسِي إِنَّ النَّفْسَ لَأَمَّارَۃٌ بِالسُّوءِ إِلَّا مَا رَحِمَ رَبِّي إِنَّ رَبِّي غَفُورٌ رَّحِيمٌ‘‘ — اور — میں — اپنے نفس — کی صفائی نہیں دیتی — بے شک — نفس — ہمیشہ — برائی — کا حکم دیتا ہے — مگر — وہ — جس — پر — میرا رب رحم کرتا ہے — بے شک — میرا رب — بخشنے والا مہربان — ہے — یعنی عزیز کی بیوی — نے کہا — میں — اپنے نفس — کی صفائی — نہیں دیتی — بے شک — نفس — ہمیشہ — برائی — کا حکم دیتا ہے — مگر وہ جس — پر — میرا رب — رحم کرتا ہے — بے شک میرا رب — غفور رحیم — ہے۔
۳۔ عملی سبق: اپنے نفس پر — بھروسہ — مت کرو؛ رحمتِ الٰہی — پر — بھروسا کرو۔"""
),
1650: (
"اور — بادشاہ — نے — کہا — یوسفؑ — کو میرے پاس — لاؤ — میں — اسے — اپنی — خاص جگہ — دوں — پس — جب — اس — نے — اس — سے — بات — کی — تو — اس — نے کہا — بے شک — آپؑ — آج — ہمارے — نزدیک — صاحب مرتبہ — اور — واحد فیصلے — کے اہل — ہیں",
"""۱۔ بادشاہ — یوسفؑ — سے متاثر — انہیں — اپنا — خاص — مقرب بنا لیتا ہے۔
۲۔ ’’وَقَالَ الْمَلِكُ ائْتُونِي بِهِ أَسْتَخْلِصْهُ لِنَفْسِي فَلَمَّا كَلَّمَهُ قَالَ إِنَّكَ الْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ‘‘ — اور — بادشاہ — نے — کہا — یوسفؑ — کو میرے پاس — لاؤ — میں — اسے — اپنی — خاص جگہ — دوں — پس — جب — اس — نے — اس — سے — بات — کی — تو — اس — نے کہا — بے شک — آپؑ — آج — ہمارے — نزدیک — صاحب مرتبہ — اور — واحد فیصلے — کے اہل — ہیں — یعنی بادشاہ نے — کہا — یوسفؑ کو میرے پاس لاؤ — میں — اسے اپنی — خاص جگہ — دوں — پس — جب — اس نے — اس سے بات کی — تو اس نے کہا — بے شک — آپ آج — ہمارے نزدیک — مکین — (صاحب مرتبہ) اور امین — (قابلِ اعتبار) ہیں۔
۳۔ عملی سبق: سچائی — عزت — لاتی ہے؛ یوسفؑ — کی — صداقت — رنگ لائی۔"""
),
1651: (
"انہوں نے کہا — مجھے — زمین — کے خزانوں — پر — مقرر — کرو — بے شک — میں — حفاظت کرنے والا جاننے والا — ہوں",
"""۱۔ یوسفؑ — زمین کے خزانوں — پر مقرر کیے جانے کی درخواست — پیشواریت — کی نمائش۔
۲۔ ’’قَالَ اجْعَلْنِي عَلَىٰ خَزَائِنِ الْأَرْضِ إِنِّي حَفِيظٌ عَلِيمٌ‘‘ — انہوں نے کہا — مجھے — زمین — کے خزانوں — پر — مقرر — کرو — بے شک — میں — حفاظت کرنے والا جاننے والا — ہوں — یعنی یوسفؑ — نے — کہا — مجھے — زمین — کے خزانوں — پر مقرر کرو — بے شک — میں — حفاظت کرنے والا — جاننے والا — ہوں۔
۳۔ عملی سبق: اہل — کو ذمہ داری — دینا — اسلام کا اصول — ہے۔"""
),
1652: (
"اور — اسی — طرح — ہم نے — یوسفؑ — کو — زمین — میں — جگہ دی — اس — میں وہ — جہاں چاہیں — رہیں؛ ہم — جس کو — چاہتے ہیں — اپنی رحمت — پہنچاتے ہیں — اور — ہم — نیک لوگوں کا اجر — ضائع — نہیں کرتے",
"""۱۔ اللہ نے — یوسفؑ کو — زمین میں — عزت اور اختیار — دیا۔
۲۔ ’’وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَاءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَاءُ وَلَا نُضِيعُ أَجْرَ الْمُحْسِنِينَ‘‘ — اور — اسی — طرح — ہم نے — یوسفؑ — کو — زمین — میں — جگہ دی — اس — میں وہ — جہاں چاہیں — رہیں؛ ہم — جس کو — چاہتے ہیں — اپنی رحمت — پہنچاتے ہیں — اور — ہم — نیک لوگوں کا اجر — ضائع — نہیں کرتے — یعنی اسی طرح — ہم نے — یوسفؑ — کو — زمین — میں — جگہ — دی — وہ — جہاں چاہیں — رہیں — ہم جس کو — چاہتے ہیں — اپنی رحمت — پہنچاتے ہیں — اور ہم — نیکوکاروں — کا اجر — ضائع — نہیں کرتے۔
۳۔ عملی سبق: نیکی — کا اجر — اللہ — یقیناً — دیتا — ہے؛ یقین — رکھو۔"""
),
1653: (
"اور — یقیناً — آخرت — کا — اجر — ان لوگوں کے لیے — بہتر — ہے — جو ایمان لائے — اور — تقویٰ — اختیار کرتے تھے",
"""۱۔ آخرت کا اجر — دنیا — سے بہتر ہے۔
۲۔ ’’وَلَأَجْرُ الْآخِرَۃِ خَيْرٌ لِّلَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ‘‘ — اور — یقیناً — آخرت — کا — اجر — ان لوگوں کے لیے — بہتر — ہے — جو ایمان لائے — اور — تقویٰ — اختیار کرتے تھے — یعنی آخرت — کا — اجر — ان لوگوں — کے لیے — بہتر ہے — جو ایمان لائے — اور تقویٰ — اختیار کرتے تھے۔
۳۔ عملی سبق: دنیا — اچھا ہے — مگر — آخرت — سب سے بہتر — ہے۔"""
),
1654: (
"اور — یوسفؑ — کے بھائی — آئے — پس — اس — کے پاس — داخل ہوئے — اس — نے — ان — کو — پہچان لیا — اور — وہ — اس — کے — منکر — تھے",
"""۱۔ بھائی — قحط سالی — میں — خوراک — لینے مصر — پہنچے۔
۲۔ ’’وَجَاءَ إِخْوَۃُ يُوسُفَ فَدَخَلُوا عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُ مُنكِرُونَ‘‘ — اور — یوسفؑ — کے بھائی — آئے — پس — اس — کے پاس — داخل ہوئے — اس — نے — ان — کو — پہچان لیا — اور — وہ — اس — کے — منکر — تھے — یعنی یوسفؑ کے بھائی — آئے — اور اس — کے پاس — داخل ہوئے — اس — نے — انہیں پہچان لیا — اور — وہ — اس — سے — ناشنا — تھے۔
۳۔ عملی سبق: حالات — دیکھ کر — انسان — کی — پہچان — ختم — ہوتی ہے۔"""
),
1655: (
"اور — جب — اس — نے — ان — کو — ان — کے سامان — سے لیس کر دیا — تو — اس — نے کہا — میرے پاس — اپنے باپ کی طرف سے — اپنا بھائی — لاؤ — کیا — تم دیکھتے نہیں — میں — پیمانہ — پورا — دیتا ہوں — اور — میں — بہترین مہمان — نواز — ہوں",
"""۱۔ یوسفؑ — بھائیوں — سے — بینیامین — کو بلوانے کی ہدایت۔
۲۔ ’’وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ائْتُونِي بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّي أُوفِي الْكَيْلَ وَأَنَا خَيْرُ الْمُنزِلِينَ‘‘ — اور — جب — اس — نے — ان — کو — ان — کے سامان — سے لیس کر دیا — تو — اس — نے کہا — میرے پاس — اپنے باپ کی طرف سے — اپنا بھائی — لاؤ — کیا — تم دیکھتے نہیں — میں — پیمانہ — پورا — دیتا ہوں — اور — میں — بہترین مہمان — نواز — ہوں — یعنی جب — اس — نے — ان — کو — ان کے سامان — سے — لیس کر دیا — تو — اس — نے کہا — میرے پاس — اپنے باپ کی طرف سے — اپنا بھائی — لاؤ — کیا — تم — نہیں دیکھتے — میں — پیمانہ — پورا — دیتا — ہوں — اور میں — بہترین مہمان — نواز — ہوں۔
۳۔ عملی سبق: یوسفؑ — حکمت — سے کام لے رہے ہیں؛ جذباتی — ردعمل — نہیں۔"""
),
1656: (
"پس — اگر — تم اسے — میرے پاس — نہ لائے — تو — تمہارا — میرے پاس — کوئی پیمانہ — نہیں — اور — نہ — تم میرے قریب — آؤ",
"""۱۔ یوسفؑ — کی شرط — بینیامین کی آمد۔
۲۔ ’’فَإِن لَّمْ تَأْتُونِي بِهِ فَلَا كَيْلَ لَكُمْ عِندِي وَلَا تَقْرَبُونِ‘‘ — پس — اگر — تم اسے — میرے پاس — نہ لائے — تو — تمہارا — میرے پاس — کوئی پیمانہ — نہیں — اور — نہ — تم میرے قریب — آؤ — یعنی پس — اگر — تم — اسے — میرے — پاس — نہ لائے — تو — تمہار — ا — میرے پاس — کوئی پیمانہ — نہیں — اور — نہ — تم — میرے — قریب — آؤ۔
۳۔ عملی سبق: شرطیں — واضح — ہوں — تو — تنازعہ — نہیں ہوتا۔"""
),
}
